<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

const props = defineProps({ playbooks: Array, sites: Array });
const blankStep = () => ({ title: '', description: '', role: 'operator' });
const form = useForm({ title: '', scope_type: 'organization', site_id: '', asset_type: '', steps: [blankStep()], authorized_roles: ['admin', 'operator'] });
const editing = ref(null);
const addStep = () => form.steps.push(blankStep());
const beginEdit = (playbook) => { editing.value = playbook.id; form.clearErrors(); Object.assign(form, { title: playbook.title, scope_type: playbook.scope_type, site_id: playbook.site_id || '', asset_type: playbook.asset_type || '', steps: playbook.current.steps.map(step => ({ ...step })), authorized_roles: [...playbook.current.authorized_roles] }); };
const reset = () => { editing.value = null; form.reset(); form.steps = [blankStep()]; };
const save = () => { const options = { preserveScroll: true, onSuccess: reset }; editing.value ? form.patch(route('playbooks.update', editing.value), options) : form.post(route('playbooks.store'), options); };
</script>

<template><Head title="Incident playbooks" /><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><h1 class="text-2xl font-semibold">Incident readiness</h1><p class="text-sm text-slate-500">Versioned procedures your team can follow under pressure.</p></div><Link :href="route('readiness.index')" class="rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white">Manual fallback register</Link></div></template><div class="mx-auto grid max-w-7xl gap-6 px-4 py-8 lg:grid-cols-[3fr_2fr]"><section class="space-y-4"><article v-for="playbook in playbooks" :key="playbook.id" class="rounded-xl border bg-white p-6 shadow-sm"><div class="flex items-start justify-between gap-4"><div><h2 class="text-lg font-semibold">{{ playbook.title }}</h2><p class="mt-1 text-xs uppercase text-slate-500">Version {{ playbook.current_version }} / {{ playbook.scope_type.replace('_', ' ') }}<span v-if="playbook.is_template"> / starter template</span></p></div><button @click="beginEdit(playbook)" class="rounded-lg border px-3 py-1.5 text-sm font-medium">Edit as new version</button></div><ol class="mt-5 space-y-3"><li v-for="(step,index) in playbook.current.steps" :key="index" class="flex gap-3"><span class="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-900 text-xs font-bold text-white">{{ index + 1 }}</span><div><p class="font-medium">{{ step.title }} <span class="text-xs font-normal uppercase text-teal-700">{{ step.role }}</span></p><p class="mt-1 text-sm text-slate-600">{{ step.description }}</p></div></li></ol></article></section><form @submit.prevent="save" class="h-fit rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">{{ editing ? 'Create a new version' : 'Create playbook' }}</h2><label class="mt-4 block text-sm font-medium">Title</label><input v-model="form.title" required class="mt-1 w-full rounded-lg border-slate-300" /><label class="mt-3 block text-sm font-medium">Applies to</label><select v-model="form.scope_type" class="mt-1 w-full rounded-lg border-slate-300"><option value="organization">Entire organization</option><option value="site">Specific site</option><option value="asset_type">Asset type</option></select><select v-if="form.scope_type === 'site'" v-model="form.site_id" required class="mt-2 w-full rounded-lg border-slate-300"><option value="">Choose site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select><input v-if="form.scope_type === 'asset_type'" v-model="form.asset_type" required class="mt-2 w-full rounded-lg border-slate-300" placeholder="e.g. plc" /><div v-for="(step,index) in form.steps" :key="index" class="mt-4 rounded-lg border p-3"><p class="text-xs font-semibold uppercase text-slate-500">Step {{ index + 1 }}</p><input v-model="step.title" required class="mt-2 w-full rounded-lg border-slate-300" placeholder="Short action title" /><textarea v-model="step.description" required rows="3" class="mt-2 w-full rounded-lg border-slate-300" placeholder="Clear instructions"></textarea><select v-model="step.role" class="mt-2 w-full rounded-lg border-slate-300"><option value="operator">Operator</option><option value="admin">Administrator</option><option value="viewer">Viewer</option><option value="auditor">Auditor</option></select></div><button type="button" @click="addStep" class="mt-3 text-sm font-semibold text-teal-700">+ Add step</button><InputError :message="form.errors.steps" /><div class="mt-5 flex gap-2"><button class="flex-1 rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white">{{ editing ? 'Save new version' : 'Create playbook' }}</button><button v-if="editing" type="button" @click="reset" class="rounded-lg border px-4 py-2 text-sm">Cancel</button></div></form></div></AuthenticatedLayout></template>
